/**
 * The 12 `EnemyInfo` assets, exported verbatim from the shipping build.
 *
 * Generated by `analysis/export_enemies_web.py`. Do not hand-edit.
 *
 * `attackSpeed` is attacks per SECOND (the original's own convention, the same one
 * `PlayerAttackSpeed` uses), so a cooldown is `1 / attackSpeed`. Claw is 0.30/s -
 * one swing every 3.33s - which is far slower than the hand-written table the port
 * shipped, and Bat is 3.00x health rather than the 0.55x that was guessed.
 *
 * `healthMultiplier` and `damageMultiplier` sit ON TOP of the level's base enemy
 * health and damage (`DatabaseManager.EnemyHealthPerLevel` / `EnemyDamagePerLevel`).
 */

export interface EnemyInfoDef {
  /** `functionName`, which is also the enum member name. */
  id: string;
  /** The original's `EnemyType` enum value. */
  enemyType: number;
  healthMultiplier: number;
  damageMultiplier: number;
  movementSpeed: number;
  attackRange: number;
  /** Attacks per second; cooldown = 1 / attackSpeed. */
  attackSpeed: number;
  isRanged: boolean;
  /** Bat 15%, GuardianBat 8%: health regained per hit as a share of max. */
  lifestealPercentOfMaxHealth: number;
  isTameable: boolean;
  baseMovementSpeedForAnimation: number;
  hasTamedPrefab: boolean;
  hitTargetGFXDuration: number;
  /** 'GuardianClaw'..'King' for the six the port never shipped, else ''. */
  slot: string;
}

